"""Bundle src/llmbench/{models,quality,bench}.py + the grid runner into a single
self-contained script (Kaggle script kernels take exactly one code file).

    python kaggle/build_kernel.py  ->  kaggle/_bundle.py
"""

import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SRC = ROOT / "src" / "llmbench"

HEADER = '''\
"""Kaggle GPU benchmark — self-contained bundle of llmbench (auto-generated by
kaggle/build_kernel.py; do not edit here). Runs the grid on the notebook's T4."""
import json, os, subprocess, sys, time

subprocess.run([sys.executable, "-m", "pip", "install", "-q", "llama-cpp-python",
    "--extra-index-url", "https://abetlen.github.io/llama-cpp-python/whl/cu124"], check=True)
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "-U", "huggingface_hub"], check=True)
os.system("nvidia-smi --query-gpu=name,memory.total --format=csv,noheader")
'''

RUNNER = '''
MODELS = os.environ.get("LLMBENCH_MODELS",
    "gemma-2-2b,qwen2.5-3b,llama-3.2-3b,qwen2.5-7b,llama-3.1-8b,qwen2.5-14b").split(",")
QUANTS = os.environ.get("LLMBENCH_QUANTS", "Q4_K_M,Q8_0").split(",")

rows = []
for mk in MODELS:
    for q in QUANTS:
        pb = REGISTRY[mk].params_b
        if pb >= 30 and q != "Q3_K_M":
            continue
        if pb >= 13 and q == "Q8_0":
            continue
        print(f"=== {mk} {q} ===", flush=True)
        t0 = time.time()
        try:
            r = run(mk, q, n_gpu_layers=-1)
            r["wall_s"] = round(time.time() - t0, 1)
            rows.append(r)
            print(json.dumps(r), flush=True)
        except Exception as e:
            print(f"FAILED {mk} {q}: {type(e).__name__}: {e}", flush=True)

out = "/kaggle/working/gpu_grid.json" if os.path.isdir("/kaggle/working") else "gpu_grid.json"
with open(out, "w") as f:
    json.dump(rows, f, indent=2)
print(f"\\nwrote {len(rows)} cells -> {out}")
'''


def strip_module(text: str) -> str:
    # drop package-relative imports, __future__, and the __main__ guard block
    text = re.sub(r"\nif __name__ == .__main__.:\n(?: {4}.*\n?)*", "\n", text)
    lines = []
    for ln in text.splitlines():
        if re.match(r"\s*from \.\s?import ", ln) or re.match(r"\s*from \.\w+ import ", ln):
            continue
        if ln.startswith("from __future__"):
            continue
        lines.append(ln)
    return "\n".join(lines)


def main():
    parts = [HEADER]
    for mod in ("models", "quality", "bench"):
        parts.append(f"\n# ---- llmbench/{mod}.py ----\n")
        parts.append(strip_module((SRC / f"{mod}.py").read_text()))
    parts.append(RUNNER)
    bundle = "\n".join(parts)
    (Path(__file__).parent / "_bundle.py").write_text(bundle)
    print(f"wrote kaggle/_bundle.py ({len(bundle.splitlines())} lines)")


if __name__ == "__main__":
    main()
